#[inline(always)]
pub fn rook_attacks(sq: usize, occupancy: u64) -> u64 {
    let occ = occupancy & ROOK_MASKS[sq];
    let idx = occ.wrapping_mul(ROOK_MAGICS[sq])
        >> (64 - ROOK_BITS[sq] as u32);
    ROOK_ATTACKS[sq][idx as usize]
}

#[inline(always)]
pub fn bishop_attacks(sq: usize, occupancy: u64) -> u64 {
    let occ = occupancy & BISHOP_MASKS[sq];
    let idx = occ.wrapping_mul(BISHOP_MAGICS[sq])
        >> (64 - BISHOP_BITS[sq] as u32);
    BISHOP_ATTACKS[sq][idx as usize]
}